// <${Icon} name="wifi" size=${18}/>. An unknown name draws a question mark.
export function Icon({ name, size = 18, cls = '' }) {
  const d = ICONS[name] || ICONS['circle-help'];
  return html`<svg class=${'ico ' + cls} width=${size} height=${size} viewBox="0 0 24 24"
    fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
    stroke-linejoin="round" aria-hidden="true" dangerouslySetInnerHTML=${{ __html: d }}/>`;
}

// Icons brought by the interface of a module: { name: drawing }. Those of the console stay.
export function addIcons(more) {
  Object.keys(more || {}).forEach((name) => {
    if (!ICONS[name] && typeof more[name] === 'string') ICONS[name] = more[name];
  });
}
